interface BaselineJobClockStop {
    clock: BaselineJobClock;
    /** The wall this run was given by the clock. */
    boundMs: number;
    /** How long the run had been going when it was stopped. A LOWER BOUND on the suite, not its cost. */
    elapsedMs: number;
    /** What abloh's step had spent in total at that moment. Measured from the process start. */
    spentMs: number;
}
