declare function containsEngineCredential(environment: Readonly<Record<string, string | undefined>>): boolean;

/** What one docker invocation did. Nothing here throws: an exit code is a fact, not a failure. */
interface DockerInvocation {
    exitCode: number | null;
    stdout: string;
    stderr: string;
    timedOut: boolean;
    outputLimitExceeded: boolean;
    spawnError?: string;
}
/** The seam a caller injects, so a test can answer for the daemon without one. */
