    readonly model: WireField<string | null, false>;
    readonly promptVersion: WireField<string, false>;
    readonly suite: WireField<"not-checked" | "green" | "regressed" | "pre-red-unchanged", false>;
    readonly discovery: WireField<"confirmed" | "unconfirmed", false>;
    /** other gaps this same candidate closes, from the kill matrix */
    readonly alsoClosesCount: WireField<number, false>;
